               end
               if(plaza(i,lanes)==2)%Self-driving car speed up
                   if(pos>plazalength)
                        count=count+1;
                        plaza(i,lanes)=0;
                        v(i,lanes)=0;
                        vmax(i,lanes)=0;
                   else
                        plaza(pos,lanes)=plaza(i,lanes);
                        v(pos,lanes)=min(v(i,lanes)+1,vmax(i,lanes));
                        vmax(pos,lanes)=vmax(i,lanes);
                        plaza(i,lanes)=0;
                        v(i,lanes)=0;
                        vmax(i,lanes)=0;
                   end
               end
         end

         for k=2:nn;%from end
             i=temp(k);
             j=temp(k-1);
             if(v(i,lanes)<=j-i-1)%no conflict
                 pos=i+v(i,lanes);
                 temp(k)=pos;
                 safety_dis=v(i,lanes)*t_response;
                 if(plaza(i,lanes)==1)%common car need to consider safety
                     if(safety_dis>gap(i,lanes))%not safe
                          %disp(’not safe’);
                          if(pos>plazalength)
                               count=count+1;
                               plaza(i,lanes)=0;
                               v_pre=max(v(i,lanes)-1,1);
                               v(i,lanes)=0;
                               vmax(i,lanes)=0;
                          else
                               plaza(pos,lanes)=plaza(i,lanes);
                               v(pos,lanes)=max(v(i,lanes)-1,1);
                               vmax(pos,lanes)=vmax(i,lanes);
                               plaza(i,lanes)=0;
                               v_pre=v(i,lanes);
                               v(i,lanes)=0;
                               vmax(i,lanes)=0;
                          end
                     else%if safe, accelerate
                        %disp(’safe’);
                        if(pos>plazalength)
                          count=count+1;
                          plaza(i,lanes)=0;
                          v_pre=v(i,lanes);%record the v before moving
                          v(i,lanes)=0;
                          vmax(i,lanes)=0;
                        else
                          plaza(pos,lanes)=plaza(i,lanes);
                          v(pos,lanes)=min(v(i,lanes)+1,vmax(i,lanes));
                          vmax(pos,lanes)=vmax(i,lanes);

