                            v(i,lanes)=0;
                            vmax(i,lanes)=0;
                           end

                       end
                   end
                   if(plaza(i,lanes)==2)%self-driving car accelerate
                       if(pos>plazalength)
                         %plaza(pos,lanes)=plaza(i,lanes);
                         %v(pos,lanes)=min(v(i,lanes)+1,vmax(i,lanes));
                         %vmax(pos,lanes)=vmax(i,lanes)
                         count=count+1;
                         plaza(i,lanes)=0;
                         v_pre=v(i,lanes);
                         v(i,lanes)=0;
                         vmax(i,lanes)=0;
                       else
                         plaza(pos,lanes)=plaza(i,lanes);
                         v(pos,lanes)=min(v(i,lanes)+1,vmax(i,lanes));
                         vmax(pos,lanes)=vmax(i,lanes);
                         plaza(i,lanes)=0;
                         v_pre=v(i,lanes);
                         v(i,lanes)=0;
                         vmax(i,lanes)=0;
                       end
                   end
               else% conflict
                   pos=j-1;%move next to the former car
                   temp(k)=pos;
                   if(pos>plazalength)
                       count=count+1;
                       plaza(i,lanes)=0;
                       v_pre=v(i,lanes);
                       v(i,lanes)=0;
                       vmax(i,lanes)=0;
                   else
                       plaza(pos,lanes)=plaza(i,lanes);
                       if(j<=plazalength)
                            v(pos,lanes)=v(j,lanes);
                       else
                            v(pos,lanes)=v(i,lanes);
                       end
                       %v(pos,lanes)=v(i,lanes);
                       vmax(pos,lanes)=vmax(i,lanes);
                       plaza(i,lanes)=0;
                       v_pre=v(i,lanes);
                       v(i,lanes)=0;
                       vmax(i,lanes)=0;
                   end
               end
         end
     end
    traffic_count=count;

